/* Generated by scripts/prepare-offline.mjs. Versioned app files only; never measurement data. */
const PREFIX='fieldflux-offline-';
const VERSION="1ed2686b4ba8758a";
const CACHE=PREFIX+VERSION;
const ASSETS=["index.html","app.css","app.js","gps-track.js","export-images.js","offline-app.js","vendor/xlsx.js","manifest.webmanifest","icons/icon-192.png","icons/icon-512.png","icons/icon-maskable-512.png","icons/apple-touch-icon.png"];
const base=new URL(self.registration.scope);
const urls=ASSETS.map(file=>new URL(file,base).href);
const known=new Set(urls);
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);try{const fetched=await Promise.all(urls.map(async url=>{const response=await fetch(new Request(url,{cache:'reload',credentials:'same-origin',redirect:'error'}));if(!response.ok)throw Error('Offline download failed: '+url);if(url.endsWith('index.html')){const html=await response.clone().text();if(!html.includes('id="projectPicker"')||!html.includes('offline-app.js'))throw Error('Unexpected app document')}return[url,response]}));for(const[url,response]of fetched)await cache.put(url,response)}catch(error){await caches.delete(CACHE);throw error}})())});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)));await self.clients.claim()})())});
self.addEventListener('fetch',event=>{const req=event.request;if(req.method!=='GET')return;const url=new URL(req.url);if(url.origin!==base.origin)return;const navigation=req.mode==='navigate'&&(url.pathname===base.pathname||url.pathname===new URL('index.html',base).pathname);const canonical=new URL(url.href);canonical.search='';canonical.hash='';if(!navigation&&!known.has(canonical.href))return;event.respondWith((async()=>{const cache=await caches.open(CACHE),cached=await cache.match(navigation?new URL('index.html',base).href:canonical.href);if(cached)return cached;try{return await fetch(req)}catch(error){return new Response('The offline app files are incomplete. Reconnect and reload Fieldflux.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}})}})())});
self.addEventListener('message',event=>{if(event.data?.type==='APPLY_UPDATE'){self.skipWaiting();return}if(event.data?.type==='OFFLINE_STATUS')event.waitUntil((async()=>{const cache=await caches.open(CACHE),present=await Promise.all(urls.map(url=>cache.match(url)));event.ports[0]?.postMessage({ready:present.every(Boolean),version:VERSION,files:ASSETS.length})})())});
